local AnnihilationUtils = import('Game.UI.FightReady.UIMainChapter.AnnihilationUtils')

--region define
local TeamStatus = {
    RECRUITING = 1, -- 招募中
    FULL       = 2, -- 队伍已满
    FINISH     = 3, -- 招募完成
}
--endregion define

--- from: Assets/BundleResources/Prefabs/OverseaChat/OverseaChatDialog.prefab
---@class OverseaChatRecruitPanelCell
---@field Env                           	OverseaChatRecruitPanelCell             
