---@field StatusTextDesc                	UnityEngine.RectTransform               
---@field JoinBtn                       	UnityEngine.RectTransform               
---@field TextNumber                    	TMPro.TextMeshProUGUI                   
---@field TextName                      	UnityEngine.UI.Text                     
---@field TextDesc                      	UnityEngine.RectTransform               
---@field ImgType                       	UnityEngine.RectTransform               
---@field MemberImgEmpty                	UnityEngine.RectTransform               
---@field MemberHeadNode                	UnityEngine.RectTransform               
---@field LeaderImgEmpty                	UnityEngine.RectTransform               
---@field LeaderHeadNode                	UnityEngine.RectTransform               
local OverseaChatRecruitPanelCell = Class("OverseaChatRecruitPanelCell")

--region lifecycle
function OverseaChatRecruitPanelCell:__init()
    self._index = nil
    self._cb    = nil
end

function OverseaChatRecruitPanelCell:__delete()
    self._index = nil
    self._cb    = nil
end

function OverseaChatRecruitPanelCell:Awake()
    self:InitHandler()
end

function OverseaChatRecruitPanelCell:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
