--region handler
function OverseaChatRecruitPanelCell:JoinBtnOnClickHandler()
    if self._cb then
        self._cb(self._index)
    end
end
--endregion handler

--region public
---刷新cell
---@param data table cell数据
---@param index integer cell序号
---@param cb function 加入按钮点击回调
function OverseaChatRecruitPanelCell:RefreshCell(data, index, cb)
    self._index = checkInt(index)
    self._cb = cb
    
    CfUtils.SetUISwitchImage(self.ImgType, data.bossTypeId)
    local activityPrefabId = isNull(data.activity) and 0 or checkNumber(data.activity.prefab)
    local comp = AnnihilationUtils.GetComponent(activityPrefabId)
    local combatTypeConf = comp:GetTypeVo(data.bossTypeId) or {}
    CfUtils.FillText(self.TextDesc, combatTypeConf.name)
    local questConf = QuestConfMgr:GetInstance():GetQuestVoById(data.questId) or {}
    CfUtils.FillText(self.TextName, questConf.name)
    CfUtils.FillText(self.TextNumber, questConf.label)

    CfUtils.SetActive(self.LeaderHeadNode, checkInt(data.mainId) > 0)
    CfUtils.SetActive(self.LeaderImgEmpty, checkInt(data.mainId) == 0)
    if checkInt(data.mainId) > 0 then
        self:RefreshHeadNode(data.mainPlayerInfo, true)
    end

    CfUtils.SetActive(self.MemberHeadNode, checkInt(data.subId) > 0)
    CfUtils.SetActive(self.MemberImgEmpty, checkInt(data.subId) == 0)
    if checkInt(data.subId) > 0 then
        self:RefreshHeadNode(data.subPlayerInfo, false)
    end

    if checkInt(data.status) == TeamStatus.RECRUITING then
        CfUtils.SetActive(self.JoinBtn, true)
        CfUtils.SetActive(self.StatusTextDesc, false)
    else
        CfUtils.SetActive(self.JoinBtn, false)
        CfUtils.SetActive(self.StatusTextDesc, true)
    end
    
end
--endregion public

--region private
---刷新headNode
---@param info table 头像数据
---@param isLeader boolean 是否是队长
function OverseaChatRecruitPanelCell:RefreshHeadNode(info, isLeader)
    local node = isLeader and self.LeaderHeadNode or self.MemberHeadNode
    local scr = CfUtils.GetLuaScr(node, "Game.Behaviours.CommonPlayerHeadNode")
    if isNotNull(scr) then
        scr:FreshAvatarFrame(info.avatar, info.avatarFrame)
    end
end
--endregion private

return OverseaChatRecruitPanelCell